aardwolf_mushclient_collection = aardwolf_mushclient_collection or {}
aardwolf_mushclient_collection.state = aardwolf_mushclient_collection.state or {}

function aardwolf_mushclient_collection.state.initialize()
  if aardwolf_mushclient_collection.state.started == nil then
    aardwolf_mushclient_collection.state.started = false
  end
end

aardwolf_mushclient_collection.settings = aardwolf_mushclient_collection.settings or {}

function aardwolf_mushclient_collection.settings.initialize()
  return { time_label_x = 0, time_label_y = 0 }
end

aardwolf_mushclient_collection.commands = aardwolf_mushclient_collection.commands or {}

function aardwolf_mushclient_collection.commands.omit_blank_line()
  deleteLine()
end

aardwolf_mushclient_collection.protocol = aardwolf_mushclient_collection.protocol or {}

function aardwolf_mushclient_collection.protocol.start()
  return true
end

function aardwolf_mushclient_collection.protocol.stop()
  return true
end

aardwolf_mushclient_collection.help = aardwolf_mushclient_collection.help or {}

function aardwolf_mushclient_collection.help.show()
  cecho("<green>Aardwolf MUSHclient Collection</green>: the Time display and blank-line omission are active.\n")
end

aardwolf_gmcp_diagnostics = aardwolf_gmcp_diagnostics or {}
aardwolf_gmcp_diagnostics.state = aardwolf_gmcp_diagnostics.state or {}

function aardwolf_gmcp_diagnostics.state.record(key, value)
  aardwolf_gmcp_diagnostics.state.values = aardwolf_gmcp_diagnostics.state.values or {}
  aardwolf_gmcp_diagnostics.state.values[key] = value
  aardwolf_gmcp_diagnostics.state.update_count = (aardwolf_gmcp_diagnostics.state.update_count or 0) + 1
end

function aardwolf_gmcp_diagnostics.state.reset()
  aardwolf_gmcp_diagnostics.state.values = {}
  aardwolf_gmcp_diagnostics.state.update_count = 0
end

function aardwolf_gmcp_diagnostics.state.summary()
  return "updates=" .. tostring(aardwolf_gmcp_diagnostics.state.update_count or 0)
end

aardwolf_gmcp_diagnostics = aardwolf_gmcp_diagnostics or {}
aardwolf_gmcp_diagnostics.settings = aardwolf_gmcp_diagnostics.settings or {}

function aardwolf_gmcp_diagnostics.settings.is_enabled()
  return aardwolf_gmcp_diagnostics.settings.enabled == true
end

function aardwolf_gmcp_diagnostics.settings.set_enabled(enabled)
  aardwolf_gmcp_diagnostics.settings.enabled = enabled and true or false
end

aardwolf_gmcp_diagnostics = aardwolf_gmcp_diagnostics or {}
aardwolf_gmcp_diagnostics.ui = aardwolf_gmcp_diagnostics.ui or {}

function aardwolf_gmcp_diagnostics.ui.message(message)
  echo("\n[aardwolf-gmcp-diagnostics] " .. tostring(message) .. "\n")
end

function aardwolf_gmcp_diagnostics.ui.status(summary)
  aardwolf_gmcp_diagnostics.ui.message("Status: " .. tostring(summary))
end

aardwolf_gmcp_diagnostics = aardwolf_gmcp_diagnostics or {}
aardwolf_gmcp_diagnostics.commands = aardwolf_gmcp_diagnostics.commands or {}

function aardwolf_gmcp_diagnostics.commands.status()
  aardwolf_gmcp_diagnostics.ui.status("logging=" .. tostring(aardwolf_gmcp_diagnostics.settings.is_enabled()) .. "; " .. aardwolf_gmcp_diagnostics.state.summary())
end

function aardwolf_gmcp_diagnostics.commands.set_enabled(enabled)
  aardwolf_gmcp_diagnostics.settings.set_enabled(enabled)
  aardwolf_gmcp_diagnostics.ui.message(enabled and "Diagnostic console logging enabled." or "Diagnostic console logging disabled.")
end

function aardwolf_gmcp_diagnostics.commands.toggle()
  aardwolf_gmcp_diagnostics.commands.set_enabled(not aardwolf_gmcp_diagnostics.settings.is_enabled())
end

function aardwolf_gmcp_diagnostics.commands.reset()
  aardwolf_gmcp_diagnostics.state.reset()
  aardwolf_gmcp_diagnostics.ui.message("Diagnostic state reset.")
end

aardwolf_gmcp_diagnostics = aardwolf_gmcp_diagnostics or {}
aardwolf_gmcp_diagnostics.protocol = aardwolf_gmcp_diagnostics.protocol or {}

function aardwolf_gmcp_diagnostics.protocol.on_room_info()
  local payload = gmcp and gmcp.room and gmcp.room.info
  if payload == nil then
    return
  end
  aardwolf_gmcp_diagnostics.state.record("room_info", payload)
  if aardwolf_gmcp_diagnostics.settings.is_enabled() then
    aardwolf_gmcp_diagnostics.ui.message("Updated from gmcp.room.info.")
  end
end

function aardwolf_gmcp_diagnostics.protocol.on_vitals()
  local payload = gmcp and gmcp.char and gmcp.char.vitals
  if payload == nil then
    return
  end
  aardwolf_gmcp_diagnostics.state.record("vitals", payload)
  if aardwolf_gmcp_diagnostics.settings.is_enabled() then
    aardwolf_gmcp_diagnostics.ui.message("Updated from gmcp.char.vitals.")
  end
end

function aardwolf_gmcp_diagnostics.protocol.on_tick()
  local payload = gmcp and gmcp.comm and gmcp.comm.tick
  if payload == nil then
    return
  end
  aardwolf_gmcp_diagnostics.state.record("tick", payload)
  if aardwolf_gmcp_diagnostics.settings.is_enabled() then
    aardwolf_gmcp_diagnostics.ui.message("Updated from gmcp.comm.tick.")
  end
end

aardwolf_gmcp_diagnostics = aardwolf_gmcp_diagnostics or {}
aardwolf_gmcp_diagnostics.lifecycle = aardwolf_gmcp_diagnostics.lifecycle or {}

function aardwolf_gmcp_diagnostics.lifecycle.initialize()
  deleteNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::room_info")
  registerNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::room_info", "gmcp.room.info", aardwolf_gmcp_diagnostics.protocol.on_room_info)
  deleteNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::vitals")
  registerNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::vitals", "gmcp.char.vitals", aardwolf_gmcp_diagnostics.protocol.on_vitals)
  deleteNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::tick")
  registerNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::tick", "gmcp.comm.tick", aardwolf_gmcp_diagnostics.protocol.on_tick)
end

function aardwolf_gmcp_diagnostics.lifecycle.shutdown()
  deleteNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::room_info")
  deleteNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::vitals")
  deleteNamedEventHandler("aardwolf_gmcp_diagnostics", "aardwolf-gmcp-diagnostics::event::tick")
end

aardwolf_gmcp_diagnostics.lifecycle.initialize()

aardwolf_gmcp_diagnostics = aardwolf_gmcp_diagnostics or {}
aardwolf_gmcp_diagnostics.help = aardwolf_gmcp_diagnostics.help or {}

function aardwolf_gmcp_diagnostics.help.summary()
  return "Safe native GMCP state diagnostics for Aardwolf."
end

aardwolf_tick = aardwolf_tick or {}
aardwolf_tick.state = aardwolf_tick.state or {}

local TICK_DURATION = 30

function aardwolf_tick.state.witness(now)
  aardwolf_tick.state.last_tick = tonumber(now) or os.time()
  aardwolf_tick.state.update_count = (aardwolf_tick.state.update_count or 0) + 1
end

function aardwolf_tick.state.remaining(now)
  if not aardwolf_tick.state.last_tick then
    return nil
  end
  return math.max(0, math.min(TICK_DURATION, math.ceil(TICK_DURATION - ((tonumber(now) or os.time()) - aardwolf_tick.state.last_tick))))
end

function aardwolf_tick.state.reset()
  aardwolf_tick.state.last_tick = nil
  aardwolf_tick.state.update_count = 0
end

function aardwolf_tick.state.summary()
  local remaining = aardwolf_tick.state.remaining()
  return remaining and (tostring(remaining) .. " seconds until next tick") or "next tick unavailable"
end

aardwolf_tick = aardwolf_tick or {}
aardwolf_tick.settings = aardwolf_tick.settings or {}

function aardwolf_tick.settings.is_enabled()
